using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using LighFight.Runtime;
public static class TripoSailorFullFootPacket {
 public static void Create(){
  var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/LighFight/Art/Drafts/TripoSailorPlayable/Source/SailorFull/model.fbx");var skin=source.GetComponentInChildren<SkinnedMeshRenderer>();var mesh=skin.sharedMesh;float ankle=Enumerable.Range(0,skin.bones.Length).Where(i=>NativeRigBones.CanonicalName(skin.bones[i].name)=="LeftFoot"||NativeRigBones.CanonicalName(skin.bones[i].name)=="RightFoot").Max(i=>skin.transform.TransformPoint(mesh.bindposes[i].inverse.MultiplyPoint3x4(Vector3.zero)).y);var vertices=mesh.vertices;var result=new List<int>();
  using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int offset=0;for(int v=0;v<vertices.Length;v++){float foot=0;for(int n=0;n<counts[v];n++){var influence=weights[offset+n];string bone=NativeRigBones.CanonicalName(skin.bones[influence.boneIndex].name);if(bone.Contains("Foot")||bone.Contains("Toe"))foot+=influence.weight;}offset+=counts[v];if(foot>0 || skin.transform.TransformPoint(vertices[v]).y<=ankle+.05f)result.Add(v);}}
  File.WriteAllLines("Assets/LighFight/Art/Drafts/TripoSailorPlayable/sole-support-full-original-vertex-indices.txt",result.Select(i=>i.ToString()));File.WriteAllText("SailorEvidence/full-support-definition.txt","Every original vertex with any foot/toe influence, union every original low shoe vertex (worldY<=max original ankleY+.05). No stride, subsampling, remeshing or replacement. Includes full-surface points with original all-weight bindpoints. Count="+result.Count+" hash="+TripoSailorFullSourcePrepare.MeshHash(mesh));AssetDatabase.Refresh();Debug.Log("AGENT_RESULT Sailor exact original full-shoe support count="+result.Count);
 }
}
